CREATE OR REPLACE FUNCTION public.fn_submit_public_capture(p_kind text, p_data jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$ DECLARE allowed_events text[] := ARRAY['page_viewed','signup_viewed','signup_submitted','signup_succeeded','signup_failed','onboarding_started','onboarding_completed','go_live_clicked','publish_page_clicked','checkout_redirected','checkout_canceled','email_lead_submitted','referral_submitted','sample_page_viewed','promo_popup_shown','promo_cta_clicked','invite_link_opened','invite_code_entered','invite_landing_viewed','signup_form_started','invite_cta_clicked','cta_clicked','demo_started','demo_completed','page_published','first_ask_prepared','pwa_install_prompted','pwa_installed','pwa_install_cta_shown','pwa_install_cta_clicked','dashboard_viewed','onboarding_step_completed','publish_banner_seen','publish_succeeded','publish_failed','share_tools_viewed','checkout_succeeded','campaigns_tab_viewed','campaign_segment_selected','campaign_preview_viewed','campaign_send_clicked','campaign_sent','campaign_send_failed','referral_page_load_failed','launch_composer_viewed','launch_send_clicked','launch_sent','launch_send_failed','launch_results_viewed','kit_ready_viewed','kit_send_clicked','intake_opened','intake_send_us_clicked','intake_import_succeeded']; BEGIN IF p_kind NOT IN ('funnel_events','mock_inquiries','callback_requests','email_leads') OR jsonb_typeof(p_data)<>'object' OR length(p_data::text)>8000 THEN RAISE EXCEPTION 'invalid_capture'; END IF; IF NOT public.fn_rate_bucket_hit('capture:'||p_kind||':'||public.fn_request_bucket(),interval '1 hour',CASE WHEN p_kind='funnel_events' THEN 300 ELSE 10 END) OR NOT public.fn_rate_bucket_hit('capture:global:'||p_kind,interval '1 hour',CASE WHEN p_kind='funnel_events' THEN 10000 ELSE 200 END) THEN RAISE EXCEPTION 'rate_limited'; END IF;
IF p_kind='funnel_events' THEN IF NOT (p_data->>'event'=ANY(allowed_events)) OR length(coalesce(p_data->>'session_id',''))>64 OR length(coalesce(p_data->>'path',''))>512 OR length(coalesce(p_data->>'referrer',''))>512 OR length(coalesce(p_data->>'user_agent',''))>512 THEN RAISE EXCEPTION 'invalid_event'; END IF; INSERT INTO public.funnel_events(event,session_id,path,referrer,user_agent,meta) VALUES(p_data->>'event',p_data->>'session_id',p_data->>'path',p_data->>'referrer',p_data->>'user_agent',coalesce(p_data->'meta','{}'::jsonb));
ELSIF p_kind='email_leads' THEN IF p_data->>'source' NOT IN ('landing','playbook','sample','marketplace_notify') OR length(coalesce(p_data->>'email',''))>254 OR p_data->>'email' !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN RAISE EXCEPTION 'invalid_email'; END IF; INSERT INTO public.email_leads(email,source) VALUES(lower(btrim(p_data->>'email')),p_data->>'source');
ELSIF p_kind='callback_requests' THEN IF length(coalesce(p_data->>'name','')) NOT BETWEEN 1 AND 200 OR length(coalesce(p_data->>'email','')) NOT BETWEEN 3 AND 254 OR p_data->>'email' !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' OR length(coalesce(p_data->>'phone',''))>32 OR length(coalesce(p_data->>'help_with',''))>2000 OR length(coalesce(p_data->>'business_name',''))>200 OR length(coalesce(p_data->>'city',''))>120 THEN RAISE EXCEPTION 'invalid_callback'; END IF; INSERT INTO public.callback_requests(name,email,phone,business_name,city,help_with,is_mock) VALUES(p_data->>'name',lower(btrim(p_data->>'email')),p_data->>'phone',p_data->>'business_name',p_data->>'city',p_data->>'help_with',false);
ELSE IF p_data->>'kind' NOT IN ('contact','quote','referral') OR length(coalesce(p_data->>'listing_slug',''))>100 OR length(coalesce(p_data->>'name',''))>200 OR length(coalesce(p_data->>'email',''))>254 OR length(coalesce(p_data->>'phone',''))>32 OR length(coalesce(p_data->>'message',''))>2000 THEN RAISE EXCEPTION 'invalid_inquiry'; END IF; INSERT INTO public.mock_inquiries(listing_slug,kind,name,email,phone,message,is_mock) VALUES(p_data->>'listing_slug',p_data->>'kind',p_data->>'name',p_data->>'email',p_data->>'phone',p_data->>'message',true); END IF; RETURN true; END $function$;